#include <stdio.h>
#include <ctype.h>

int main() {
    char s[] = "Code 4 Fun";
    for (int i = 0; s[i] != '\0'; i++) {
        if (isalpha(s[i])) {
            s[i] = (s[i] >= 'a' && s[i] <= 'z') ? toupper(s[i]) : tolower(s[i]);
        }
    }
    printf("%s\n", s);
    return 0;
}
